import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();ws.onmessage=({data})=>{const m=JSON.parse(data);if(pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
try {
 for(const [profile,width,height,mobile]of [['desktop',960,540,false],['android',390,844,true]]) {
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});
  await send('Emulation.setUserAgentOverride',{userAgent:mobile?'Mozilla/5.0 (Linux; Android 14) Mobile':'Mozilla/5.0 (Macintosh)'});
  await send('Page.navigate',{url:'http://127.0.0.1:3001/'});await wait(500);
  for(let i=0;i<100&&!await evaluate('Boolean(window.game)');i++)await wait(100);
  await evaluate('game.assetsReady');
  const initial=await evaluate(`({values:[...document.querySelector('#debug-phase-select').options].map(o=>o.value),bounds:document.querySelector('#btn-debug-phase-toggle').getBoundingClientRect().toJSON(),hidden:document.querySelector('#debug-phase-panel').hidden,expanded:document.querySelector('#btn-debug-phase-toggle').getAttribute('aria-expanded')})`);
  assert.equal(initial.hidden,true,'Seletor começa recolhido');assert.equal(initial.expanded,'false');assert.deepEqual(initial.values,['','bedroom','toy-room','arena']);assert.ok(initial.bounds.x>=0&&initial.bounds.right<=width);
  await evaluate(`game.newCampaign();game.start('NORMAL');game.saveProgress();`);await wait(100);
  const jump=phase=>evaluate(`(()=>{const toggle=document.querySelector('#btn-debug-phase-toggle');toggle.click();if(document.querySelector('#debug-phase-panel').hidden||toggle.getAttribute('aria-expanded')!=='true')throw Error('Ícone não abriu o seletor');const bounds=document.querySelector('#debug-phase-panel').getBoundingClientRect();if(bounds.left<0||bounds.right>innerWidth)throw Error('Painel fora da tela');const s=document.querySelector('#debug-phase-select');s.value=${JSON.stringify(phase)};s.dispatchEvent(new Event('change',{bubbles:true}));return s.value;})()`);
  assert.equal(await jump('bedroom'),'');await wait(100);
  const saved=await evaluate(`localStorage.getItem('legendGirl.campaign.v1')`);assert.ok(saved,'Campanha normal já possui save');
  for(const phase of ['toy-room','arena','bedroom','arena','toy-room']) {
   assert.equal(await jump(phase),'');
   let status;for(let i=0;i<150;i++){
    status=await evaluate(`({mode:game.state.currentPhaseMode,arena:game.state.toyRoomInstance?.instance?.arena?.state.status,panelHidden:document.querySelector('#debug-phase-panel').hidden,focusInMenu:document.querySelector('.phase-debug-menu').contains(document.activeElement),paused:game.isPaused()})`);
    if(phase==='bedroom'?status.mode==='bedroom':phase==='arena'?status.arena==='COMBAT':status.mode==='toy-room'&&status.arena==='IDLE')break;await wait(100);
   }
   assert.equal(status.mode,phase==='bedroom'?'bedroom':'toy-room');if(phase==='arena')assert.equal(status.arena,'COMBAT');
   assert.equal(status.panelHidden,true,'Escolher fase recolhe o painel');assert.equal(status.focusInMenu,false,'Seleção libera teclado para o jogo');assert.equal(status.paused,false);
   await evaluate('game.saveProgress()');assert.equal(await evaluate(`localStorage.getItem('legendGirl.campaign.v1')`),saved,'Debug preserva save');
  }
  const key=await evaluate(`(()=>{document.querySelector('#btn-debug-phase-toggle').click();const s=document.querySelector('#debug-phase-select');s.focus();s.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyP',key:'p',bubbles:true}));return game.isPaused();})()`);assert.equal(key,false,'Select não aciona pausa');
  assert.equal(await evaluate(`(()=>{const s=document.querySelector('#debug-phase-select');s.dispatchEvent(new KeyboardEvent('keydown',{code:'Escape',key:'Escape',bubbles:true}));return document.querySelector('#debug-phase-panel').hidden&&document.activeElement.id==='btn-debug-phase-toggle';})()`),true,'Escape recolhe e devolve foco ao ícone');
  assert.equal(await evaluate(`(()=>{document.querySelector('#btn-debug-phase-toggle').click();document.body.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true}));return document.querySelector('#debug-phase-panel').hidden;})()`),true,'Clique fora recolhe');
  await evaluate('game.restartToTitle()');assert.equal(await evaluate(`localStorage.getItem('legendGirl.campaign.v1')`),saved);
  console.log('APROVADO: '+profile+' — três fases, troca repetida durante jogo, arena com espada, seletor dentro da tela, teclado isolado e save preservado.');
 }
} finally {ws.close();}
